package main

import (
	"context"
	"encoding/json"
	"os"
	"testing"
	"time"

	"github.com/corentings/chess/v2"
)

func TestNullEligibility(t *testing.T) {
	for _, c := range []struct {
		fen           string
		depth, beta   int
		checked, want bool
	}{
		{"rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1", 3, 0, false, true},
		{"rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR b KQkq - 0 1", 3, 0, false, true},
		{"4k3/8/8/8/8/8/P7/4K3 w - - 0 1", 5, 0, false, false},
		{"4k3/8/8/8/8/8/P7/4K3 b - - 0 1", 5, 0, false, false},
		{"4k3/8/8/8/8/8/P7/3RK3 w - - 0 1", 2, 0, false, false},
		{"4k3/8/8/8/8/8/P7/3RK3 w - - 0 1", 5, 0, true, false},
		{"4k3/8/8/8/8/8/P7/3RK3 w - - 0 1", 5, mateScore, false, false},
		{"4k3/8/8/8/8/8/P7/3RK3 w - - 0 1", 5, -mateScore, false, false},
	} {
		if got := nullEligible(evalFEN(t, c.fen), c.depth, c.beta, c.checked); got != c.want {
			t.Fatalf("%s: eligibility %v want %v", c.fen, got, c.want)
		}
	}
}

func TestNullPassState(t *testing.T) {
	p := evalFEN(t, "r3k2r/8/8/3pP3/8/8/8/R3K2R w KQkq d6 0 7")
	before := p.String()
	passed := p.Update(nil)
	if passed.Turn() != chess.Black || passed.EnPassantSquare() != chess.NoSquare || passed.Board().String() != p.Board().String() || passed.CastleRights() != p.CastleRights() {
		t.Fatal("invalid hypothetical pass state")
	}
	if before != p.String() || passed.ZobristHash() == p.ZobristHash() {
		t.Fatal("pass mutated parent or retained its key")
	}
}

func TestNullCutoffIsBoundAndDoesNotPolluteTable(t *testing.T) {
	p := chess.NewGame().Position()
	before := p.String()
	w := searcher{table: newTable()}
	score, ok := w.search(p, 4, -1001, -1000, false)
	if !ok || score != -1000 {
		t.Fatalf("bound %d complete %v", score, ok)
	}
	for _, e := range w.table.entries {
		if e.bound != noBound {
			t.Fatal("hypothetical pass polluted real-position table")
		}
	}
	ref := searcher{reference: true}
	s, done := ref.search(p, 4, -1001, -1000, false)
	if !done || s < -1000 || w.nodes >= ref.nodes {
		t.Fatalf("cutoff failed reference: scores %d/%d nodes %d/%d", score, s, w.nodes, ref.nodes)
	}
	if before != p.String() {
		t.Fatal("root mutated")
	}
}

func TestNullCancellationIsNotScore(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	calls := 0
	w := searcher{ctx: ctx, table: newTable(), now: func() time.Time {
		calls++
		if calls == 4 {
			cancel()
		}
		return time.Time{}
	}, deadline: time.Now().Add(time.Hour)}
	_, complete := w.search(chess.NewGame().Position(), 5, -1001, -1000, false)
	if complete || ctx.Err() == nil {
		t.Fatal("cancelled null probe became completed score")
	}
	for _, e := range w.table.entries {
		if e.bound != noBound {
			t.Fatal("cancelled probe stored a score")
		}
	}
}

// An opt-in fixed-depth diagnostic saves raw measurements without LLM per-position work.
func TestNullAudit(t *testing.T) {
	path := os.Getenv("PANDAFISH_NULL_AUDIT")
	if path == "" {
		t.Skip("offline diagnostic")
	}
	data, err := os.ReadFile("tools/benchmark/results/v0.15-evaluation-dev-vs-v0.14.1-and-stockfish-2-and-sacrifice-v0.2.0-b528f0ba/position-inputs.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Cases []struct {
			FEN string `json:"fen"`
		}
	}
	if err = json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	type row struct {
		FEN           string
		Reference     bool
		Depth, Score  int
		Move, Request string
		Nodes         uint64
		Milliseconds  float64
	}
	var rows []row
	for _, c := range fixture.Cases {
		p := evalFEN(t, c.FEN)
		for _, ref := range []bool{true, false} {
			w := searcher{reference: ref, table: newTable(), killers: new(killerTable)}
			start := time.Now()
			score, complete := w.search(p, 4, -searchInfinity, searchInfinity, inCheck(p))
			if !complete {
				t.Fatal("unfinished audit")
			}
			rows = append(rows, row{FEN: c.FEN, Reference: ref, Depth: 4, Score: score, Request: "depth 4", Nodes: w.nodes, Milliseconds: float64(time.Since(start)) / float64(time.Millisecond)})
		}
		for _, ref := range []bool{true, false} {
			limits := goLimits{moveTime: 100 * time.Millisecond, hasTime: true}
			budget, err := limits.budget(p.Turn())
			if err != nil {
				t.Fatal(err)
			}
			start := time.Now()
			w := searcher{reference: ref, table: newTable(), killers: new(killerTable), deadline: start.Add(budget.hard)}
			r := w.iterate(p, rootMoves(p, nil), 0, budget, start)
			legal := false
			for _, m := range p.ValidMoves() {
				if m.String() == r.move {
					legal = true
				}
			}
			if p.Status() == chess.NoMethod && !legal {
				t.Fatal("illegal timed move", c.FEN, r.move)
			}
			rows = append(rows, row{FEN: c.FEN, Reference: ref, Depth: r.depth, Score: r.score, Move: r.move, Request: "movetime 100", Nodes: w.nodes, Milliseconds: float64(time.Since(start)) / float64(time.Millisecond)})
		}
	}
	out, err := json.MarshalIndent(rows, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err = os.WriteFile(path, append(out, '\n'), 0644); err != nil {
		t.Fatal(err)
	}
}

